struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// T1354b — furnace atmosphere (generated by src/projects/furnace/atmosphere.ts from the GLB).
struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane — depth arrives as distance ÷ far.
  density: f32, // @default 0.018  Smoke extinction per metre at the floor.
  roofSmoke: f32, // @default 0.6  Extra smoke pooled under the roof.
  turbulence: f32, // @default 0.7  How lumpy and drifting the smoke is.
  ambientSmoke: vec3f, // @default 0.012  Base light the smoke carries everywhere (linear).
  furnaceGlow: f32, // @default 60  Glow of the open furnace in the smoke.
  arcFlash: f32, // @default 10  The arc's blue-white flash in the smoke (flicker it).
  slagGlow: f32, // @default 25  Slag door glow.
  tapGlow: f32, // @default 15  Tapping stream glow.
  tundishGlow: f32, // @default 12  Caster tundish glow.
  lamps: f32, // @default 8  Sodium high-bay lamps.
  shafts: f32, // @default 2.5  Brightness of the light shafts under the roof louvres.
  shaftColor: vec3f, // @default 0.75  Colour of the shafts (daylight through smoke).
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

const LIGHT_COUNT: u32 = 9u;
const LIGHT_POSITION = array<vec3f, 9>(vec3f(0.0000, 13.2000, 0.0000), vec3f(0.0000, 10.4500, 0.0000), vec3f(-5.1000, 9.2000, 0.0000), vec3f(5.2500, 4.4000, 0.0000), vec3f(38.0000, 14.2000, 6.0000), vec3f(-36.0000, 28.7000, 0.0000), vec3f(-12.0000, 28.7000, 0.0000), vec3f(12.0000, 28.7000, 0.0000), vec3f(36.0000, 28.7000, 0.0000));
const SHAFT_COUNT: u32 = 10u;
const SHAFT_TOP = array<vec3f, 10>(vec3f(-54.0000, 35.6000, -3.9000), vec3f(-42.0000, 35.6000, 3.9000), vec3f(-30.0000, 35.6000, -3.9000), vec3f(-18.0000, 35.6000, 3.9000), vec3f(-6.0000, 35.6000, -3.9000), vec3f(6.0000, 35.6000, 3.9000), vec3f(18.0000, 35.6000, -3.9000), vec3f(30.0000, 35.6000, 3.9000), vec3f(42.0000, 35.6000, -3.9000), vec3f(54.0000, 35.6000, 3.9000));
const SHAFT_DIRECTION: vec3f = vec3f(0.2210, -0.5525, -0.8037);
const SHAFT_RADIUS: f32 = 1.8;
const STEPS: u32 = 28u;

fn lightRadiance(index: u32) -> vec3f {
  switch index {
    case 0u: { return vec3f(1.0000, 0.4200, 0.1200) * params.furnaceGlow; }
    case 1u: { return vec3f(0.6200, 0.7200, 1.0000) * params.arcFlash; }
    case 2u: { return vec3f(1.0000, 0.3500, 0.0800) * params.slagGlow; }
    case 3u: { return vec3f(1.0000, 0.5000, 0.1500) * params.tapGlow; }
    case 4u: { return vec3f(1.0000, 0.4500, 0.1400) * params.tundishGlow; }
    case 5u: { return vec3f(1.0000, 0.6200, 0.3000) * params.lamps; }
    case 6u: { return vec3f(1.0000, 0.6200, 0.3000) * params.lamps; }
    case 7u: { return vec3f(1.0000, 0.6200, 0.3000) * params.lamps; }
    case 8u: { return vec3f(1.0000, 0.6200, 0.3000) * params.lamps; }
    default: { return vec3f(0.0); }
  }
}

fn airHash(p: vec3f) -> f32 {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.x + q.y) * q.z);
}

fn airNoise(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(airHash(i), airHash(i + vec3f(1.0, 0.0, 0.0)), u.x), mix(airHash(i + vec3f(0.0, 1.0, 0.0)), airHash(i + vec3f(1.0, 1.0, 0.0)), u.x), u.y),
    mix(mix(airHash(i + vec3f(0.0, 0.0, 1.0)), airHash(i + vec3f(1.0, 0.0, 1.0)), u.x), mix(airHash(i + vec3f(0.0, 1.0, 1.0)), airHash(i + vec3f(1.0, 1.0, 1.0)), u.x), u.y),
    u.z,
  );
}

fn smoke(x: vec3f, time: f32) -> f32 {
  let floorLayer = exp(-max(x.y, 0.0) * 0.07);
  let roofLayer = smoothstep(18.0, 32.0, x.y) * params.roofSmoke;
  let drift = vec3f(time * 0.35, time * 0.12, time * 0.2);
  let lumps = airNoise(x * 0.09 + drift * 0.09) * 0.65 + airNoise(x * 0.23 - drift * 0.2) * 0.35;
  let shape = mix(1.0, lumps * 2.0, params.turbulence);
  return params.density * (floorLayer + roofLayer) * max(shape, 0.0);
}

// Henyey-Greenstein, g = 0.35: smoke scatters mostly forward, so a light behind the haze blooms.
fn phase(cosTheta: f32) -> f32 {
  let g = 0.35;
  let denominator = 1.0 + g * g - 2.0 * g * cosTheta;
  return (1.0 - g * g) / (12.566371 * pow(denominator, 1.5));
}

fn shaftDensity(x: vec3f) -> f32 {
  var total = 0.0;
  for (var i = 0u; i < SHAFT_COUNT; i = i + 1u) {
    let offset = x - SHAFT_TOP[i];
    let along = dot(offset, SHAFT_DIRECTION);
    if (along < 0.0 || along > 70.0) { continue; }
    let across = length(offset - SHAFT_DIRECTION * along);
    total = total + exp(-(across * across) / (SHAFT_RADIUS * SHAFT_RADIUS)) * (1.0 - along / 70.0);
  }
  return total;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let sample = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  let forward = normalize(params.aim - params.eye);
  let right = normalize(cross(forward, vec3f(0.0, 1.0, 0.0)));
  let up = cross(right, forward);
  let tanHalf = tan(radians(params.fov) * 0.5);
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  let direction = normalize(forward + right * ndc.x * tanHalf * aspect + up * ndc.y * tanHalf);
  // Depth is linear view distance ÷ far; the background (depth 1) marches to a fixed horizon.
  let depth = sample.a;
  let distance = select(depth * params.far, 140.0, depth >= 0.9999);
  let step = distance / f32(STEPS);
  // Interleaved gradient noise: a dither the eye reads as texture, not as speckle.
  let pixel = uv * frameU.resolution + vec2f(frameU.absFrame * 5.588238);
  let jitter = fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
  var transmittance = 1.0;
  var scatter = vec3f(0.0);
  for (var k = 0u; k < STEPS; k = k + 1u) {
    let x = params.eye + direction * (f32(k) + jitter) * step;
    let sigma = smoke(x, frameU.absTime);
    var inscatter = params.ambientSmoke;
    for (var i = 0u; i < LIGHT_COUNT; i = i + 1u) {
      let toLight = LIGHT_POSITION[i] - x;
      let d2 = dot(toLight, toLight);
      inscatter = inscatter + lightRadiance(i) * phase(dot(direction, toLight / sqrt(max(d2, 1e-4)))) / (1.0 + d2);
    }
    inscatter = inscatter + params.shaftColor * params.shafts * shaftDensity(x) * phase(dot(direction, -SHAFT_DIRECTION));
    scatter = scatter + transmittance * sigma * inscatter * step;
    transmittance = transmittance * exp(-sigma * step);
  }
  return vec4f(sample.rgb * transmittance + scatter, 1.0);
}

struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

struct Params {
  windows: f32, // @default 1.4  Radiance of the side-window bands.
  skylights: f32, // @default 0.9  Radiance of the roof skylights.
  roof: f32, // @default 0.012  Radiance of the dark roof.
  floorBounce: f32, // @default 0.035  Warm light bounced off the floor.
  sun: f32, // @default 6  Radiance of the sun seen through the windows.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

const SUN_DIRECTION: vec3f = vec3f(-0.2210, 0.5525, 0.8037);

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  // Keep the input bound (the node requires one); its value never reaches the picture.
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let phi = (uv.x - 0.5) * 6.2831853;
  let theta = uv.y * 3.1415927;
  let d = vec3f(sin(theta) * sin(phi), cos(theta), -sin(theta) * cos(phi));
  var radiance = mix(vec3f(0.035, 0.022, 0.014) * params.floorBounce / 0.035, vec3f(0.6, 0.66, 0.78) * params.roof, smoothstep(-0.2, 0.3, d.y));
  // Side windows: horizontal bands facing ±Z, between low and high elevation, mullioned.
  let side = abs(d.z);
  let band = smoothstep(0.05, 0.12, d.y) * (1.0 - smoothstep(0.32, 0.42, d.y)) * smoothstep(0.55, 0.8, side);
  let mullions = step(0.18, fract(atan2(d.x, side) * 7.0));
  radiance = radiance + vec3f(0.7, 0.8, 1.0) * params.windows * band * mullions;
  // Skylights: a strip along the roof ridge (X).
  let ridge = smoothstep(0.85, 0.97, d.y) * (1.0 - smoothstep(0.08, 0.2, abs(d.z)));
  radiance = radiance + vec3f(0.75, 0.82, 1.0) * params.skylights * ridge * step(0.4, fract(d.x * 3.0));
  // The sun, low, seen through the window side.
  radiance = radiance + vec3f(1.0, 0.9, 0.75) * params.sun * pow(max(dot(d, SUN_DIRECTION), 0.0), 900.0);
  return vec4f(radiance + vec3f(unused), 1.0);
}

struct Params {
  exposure: f32, // @default 0  Exposure in stops.
  contrast: f32, // @default 1.08  Contrast around mid-grey after the curve.
  saturation: f32, // @default 0.92  1 keeps colour; lower desaturates the steel.
  shadowTint: vec3f, // @default 0.9  Colour pushed into the shadows (teal-steel).
  highlightTint: vec3f, // @default 1  Colour pushed into the highlights (warm).
  split: f32, // @default 0.35  Strength of the shadow / highlight split.
  aberration: f32, // @default 0.0025  Lateral chromatic aberration at the frame edge.
  vignette: f32, // @default 0.45  Darkening toward the corners.
  grain: f32, // @default 0.035  Film grain amount.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;

fn gradeHash(p: vec3f) -> f32 {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.x + q.y) * q.z);
}

// Narkowicz's ACES fit with the input pre-scaled, so 1.0 in lands near 0.8 out.
fn filmic(x: vec3f) -> vec3f {
  let a = x * 0.6;
  return clamp((a * (2.51 * a + 0.03)) / (a * (2.43 * a + 0.59) + 0.14), vec3f(0.0), vec3f(1.0));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let centre = uv - vec2f(0.5);
  let edge = dot(centre, centre);
  let shift = centre * params.aberration * (1.0 + edge * 4.0);
  let r = textureSampleLevel(inputTexture, inputSampler, uv + shift, 0.0).r;
  let g = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).g;
  let b = textureSampleLevel(inputTexture, inputSampler, uv - shift, 0.0).b;
  var color = vec3f(r, g, b) * exp2(params.exposure);
  color = filmic(color);
  let luma = dot(color, vec3f(0.2126, 0.7152, 0.0722));
  color = mix(vec3f(luma), color, params.saturation);
  let shadowWeight = (1.0 - smoothstep(0.0, 0.45, luma)) * params.split;
  let highlightWeight = smoothstep(0.4, 1.0, luma) * params.split;
  color = color * mix(vec3f(1.0), params.shadowTint, shadowWeight) * mix(vec3f(1.0), params.highlightTint, highlightWeight);
  color = clamp((color - 0.18) * params.contrast + 0.18, vec3f(0.0), vec3f(1.0));
  color = color * (1.0 - params.vignette * smoothstep(0.08, 0.5, edge));
  let noise = gradeHash(vec3f(uv * frameU.resolution, frameU.absFrame)) - 0.5;
  color = color + noise * params.grain * (0.4 + 0.6 * (1.0 - luma));
  return vec4f(clamp(color, vec3f(0.0), vec3f(1.0)), 1.0);
}

parameters.kernel:
// T1354b — the machine rig (generated by src/projects/furnace/rig-kernel.ts from the GLB).
// Each vertex's part is surface.w; its motion applies about the part's REST pivot, then its
// parent's, child first. Stateless: the rest pose is read from upstream every frame.
struct Params {
  shellTilt: f32, // @default 0  Furnace shell tilt about the rocker, radians (+ tips toward the tap).
  roofLift: f32, // @default 0  Roof lift, metres.
  roofSwing: f32, // @default 0  Roof swing about its column, radians.
  electrode1: f32, // @default 0  Electrode 1 travel, metres (negative = down into the bath).
  electrode2: f32, // @default 0  Electrode 2 travel, metres.
  electrode3: f32, // @default 0  Electrode 3 travel, metres.
  craneX: f32, // @default 0  Scrap crane bridge travel along the bay, metres.
  trolley: f32, // @default 0  Scrap crane trolley travel across the bridge, metres.
  hook: f32, // @default 0  Scrap crane hook height, metres (negative lowers).
  bucketSway: f32, // @default 0  Scrap bucket sway on the hook, radians.
  bucketOpen: f32, // @default 0  Clamshell jaw opening, radians.
  crane2X: f32, // @default 0  Ladle crane bridge travel, metres.
  trolley2: f32, // @default 0  Ladle crane trolley travel, metres.
  hook2: f32, // @default 0  Ladle crane hook height, metres.
  ladleCar: f32, // @default 0  Ladle transfer car travel on its rails, metres.
  ladleTilt: f32, // @default 0  Ladle pour tilt about the trunnions, radians.
  slagTilt: f32, // @default 0  Slag pot tilt, radians.
  turret: f32, // @default 0  Ladle turret rotation, radians.
  casting: f32, // @default 0  Caster strand travel (uv scroll), metres.
  conveyor: f32, // @default 0  Conveyor belt travel (uv scroll), metres.
};

const RIG_PARTS: u32 = 28u;
const RIG_PARENT = array<u32, 28>(0u, 0u, 1u, 1u, 1u, 1u, 0u, 6u, 7u, 8u, 9u, 9u, 7u, 0u, 13u, 14u, 14u, 0u, 17u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
const RIG_PIVOT = array<vec3f, 28>(vec3f(0.0), vec3f(0.0000, 10.8000, 0.0000), vec3f(-0.5889, 9.4500, 0.3400), vec3f(0.0000, 9.4500, -0.6800), vec3f(0.5889, 9.4500, 0.3400), vec3f(4.4000, 12.5600, -5.9000), vec3f(-10.5000, 24.0000, 0.0000), vec3f(-10.5000, 26.6500, 4.2000), vec3f(-10.5000, 21.0000, 4.2000), vec3f(-10.5000, 19.5500, 4.2000), vec3f(-8.2500, 14.4500, 4.2000), vec3f(-12.7500, 14.4500, 4.2000), vec3f(-10.5000, 28.4500, 4.2000), vec3f(27.0000, 24.0000, 0.0000), vec3f(27.0000, 26.6500, -2.5000), vec3f(27.0000, 19.5000, -2.5000), vec3f(27.0000, 28.4500, -2.5000), vec3f(16.0000, 0.0000, 0.0000), vec3f(16.0000, 4.1200, 0.0000), vec3f(-8.3000, 2.4940, 0.0000), vec3f(38.0000, 12.0000, 0.4000), vec3f(38.1067, 9.5803, 6.0000), vec3f(38.9875, 6.7825, 6.0000), vec3f(40.7798, 4.2852, 6.0000), vec3f(43.1908, 2.5335, 6.0000), vec3f(45.9827, 1.6219, 6.0000), vec3f(38.0000, 11.0000, 6.0000), vec3f(-46.0000, 1.6000, 11.0000));

fn axisAngle(axis: vec3f, angle: f32) -> mat3x3f {
  let c = cos(angle);
  let s = sin(angle);
  let t = 1.0 - c;
  let a = normalize(axis);
  return mat3x3f(
    vec3f(t * a.x * a.x + c, t * a.x * a.y + s * a.z, t * a.x * a.z - s * a.y),
    vec3f(t * a.x * a.y - s * a.z, t * a.y * a.y + c, t * a.y * a.z + s * a.x),
    vec3f(t * a.x * a.z + s * a.y, t * a.y * a.z - s * a.x, t * a.z * a.z + c),
  );
}

fn moveOne(part: u32, p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let pivot = RIG_PIVOT[part];
  switch part {
    case 1u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.shellTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 5u: { let r = axisAngle(vec3f(0.0, 1.0, 0.0), ctx.params.roofSwing); q.position = pivot + r * (q.position - pivot) + vec3f(0.0, ctx.params.roofLift, 0.0); q.normal = r * q.normal; }
    case 2u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode1; }
    case 3u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode2; }
    case 4u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.electrode3; }
    case 6u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.craneX; }
    case 7u: { q.position = q.position + vec3f(0.0, 0.0, -1.0) * ctx.params.trolley; }
    case 8u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.hook; }
    case 12u: { let stretch = max(0.01, (7.4500 - ctx.params.hook) / 7.4500); q.position.y = pivot.y + (q.position.y - pivot.y) * stretch; }
    case 9u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.bucketSway); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 10u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.bucketOpen); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 11u: { let r = axisAngle(vec3f(0.0, 0.0, -1.0), ctx.params.bucketOpen); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 13u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.crane2X; }
    case 14u: { q.position = q.position + vec3f(0.0, 0.0, -1.0) * ctx.params.trolley2; }
    case 15u: { q.position = q.position + vec3f(0.0, 1.0, 0.0) * ctx.params.hook2; }
    case 16u: { let stretch = max(0.01, (8.9500 - ctx.params.hook2) / 8.9500); q.position.y = pivot.y + (q.position.y - pivot.y) * stretch; }
    case 17u: { q.position = q.position + vec3f(1.0, 0.0, 0.0) * ctx.params.ladleCar; }
    case 18u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.ladleTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 19u: { let r = axisAngle(vec3f(0.0, 0.0, 1.0), ctx.params.slagTilt); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 20u: { let r = axisAngle(vec3f(0.0, 1.0, 0.0), ctx.params.turret); q.position = pivot + r * (q.position - pivot); q.normal = r * q.normal; }
    case 21u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 22u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 23u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 24u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 25u: { q.uv.y = q.uv.y + ctx.params.casting; }
    case 26u: { q.uv.x = q.uv.x + ctx.params.casting; }
    case 27u: { q.uv.x = q.uv.x + ctx.params.conveyor; }
    default: {}
  }
  return q;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  var part = u32(max(p.surface.w, 0.0) + 0.5);
  // Child first, then each ancestor — at most six levels (hook ← trolley ← bridge).
  for (var level = 0u; level < 6u; level = level + 1u) {
    if (part == 0u || part >= RIG_PARTS) { break; }
    q = moveOne(part, q, ctx);
    part = RIG_PARENT[part];
  }
  return q;
}

// T1354b — furnace sparks (generated by src/projects/furnace/sparks-kernel.ts from the GLB markers).
struct Params {
  tapRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  slagRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  arcRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  torchRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  pourRate: f32, // @default 0.3  Share of this emitter's sparks alive (0..1).
  brightness: f32, // @default 6  HDR radiance of a fresh spark.
  streak: f32, // @default 0.035  Streak length in seconds of flight.
  gravity: f32, // @default 9.81  Metres per second squared.
};

const EMITTER_COUNT: u32 = 8u;
const EMITTER_ORIGIN = array<vec3f, 8>(vec3f(4.9500, 6.3000, 0.0000), vec3f(-5.0000, 9.3000, 0.0000), vec3f(-0.5889, 9.4500, 0.3400), vec3f(0.0000, 9.4500, -0.6800), vec3f(0.5889, 9.4500, 0.3400), vec3f(3.9000, 12.5500, 0.0000), vec3f(56.5000, 1.3750, 6.0000), vec3f(18.3300, 5.7000, 0.0000));
const EMITTER_DIRECTION = array<vec3f, 8>(vec3f(0.9439, 0.3304, 0.0000), vec3f(-0.8944, 0.4472, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.0000, 1.0000, 0.0000), vec3f(0.2873, 0.9578, 0.0000), vec3f(0.0000, 0.1961, 0.9806), vec3f(0.9806, 0.1961, 0.0000));
// spread (radians), speed min, speed max, life min
const EMITTER_TUNING = array<vec4f, 8>(vec4f(0.550, 4.00, 9.00, 0.80), vec4f(0.700, 3.00, 8.00, 0.70), vec4f(1.100, 6.00, 14.00, 0.25), vec4f(1.100, 6.00, 14.00, 0.25), vec4f(1.100, 6.00, 14.00, 0.25), vec4f(0.600, 4.00, 9.00, 0.30), vec4f(0.350, 3.00, 7.00, 0.50), vec4f(0.600, 2.00, 6.00, 0.80));
const EMITTER_LIFE_MAX = array<f32, 8>(1.80, 1.60, 0.70, 0.70, 0.70, 0.80, 1.20, 1.60);
const DRAG: f32 = 0.9;
const FLOOR: f32 = 0.03;

fn emitterRate(index: u32, ctx: PointCtx) -> f32 {
  switch index {
    case 0u: { return ctx.params.tapRate; }
    case 1u: { return ctx.params.slagRate; }
    case 2u: { return ctx.params.arcRate; }
    case 3u: { return ctx.params.arcRate; }
    case 4u: { return ctx.params.arcRate; }
    case 5u: { return ctx.params.arcRate; }
    case 6u: { return ctx.params.torchRate; }
    case 7u: { return ctx.params.pourRate; }
    default: { return 0.0; }
  }
}

fn sparkHash(a: u32, b: u32) -> f32 {
  var h = a * 747796405u + b * 2891336453u + 12345u;
  h = ((h >> ((h >> 28u) + 4u)) ^ h) * 277803737u;
  h = (h >> 22u) ^ h;
  return f32(h) / 4294967295.0;
}

// Blackbody-ish ramp for a cooling spark: white-yellow fresh, deep orange, then red.
fn sparkHeat(heat: f32) -> vec3f {
  let h = clamp(heat, 0.0, 1.0);
  return mix(vec3f(1.0, 0.18, 0.02), mix(vec3f(1.0, 0.55, 0.12), vec3f(1.0, 0.92, 0.7), smoothstep(0.55, 1.0, h)), smoothstep(0.0, 0.55, h));
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let id = ctx.index;
  let emitter = id % EMITTER_COUNT;
  let tuning = EMITTER_TUNING[emitter];
  let life = mix(tuning.w, EMITTER_LIFE_MAX[emitter], sparkHash(id, 1u));
  let clock = ctx.absTime / life + sparkHash(id, 2u);
  let cycle = u32(floor(clock));
  let t = fract(clock) * life;
  let origin = EMITTER_ORIGIN[emitter];
  let alive = sparkHash(id, cycle * 7u + 3u) < clamp(emitterRate(emitter, ctx), 0.0, 1.0);
  if (!alive) {
    q.position = origin;
    q.endpoint = origin;
    q.tint = vec4f(0.0);
    return q;
  }
  // Launch: a cone around the emitter's direction, re-rolled every cycle.
  let axis = EMITTER_DIRECTION[emitter];
  let helper = select(vec3f(0.0, 1.0, 0.0), vec3f(1.0, 0.0, 0.0), abs(axis.y) > 0.9);
  let side = normalize(cross(axis, helper));
  let up = cross(side, axis);
  let angle = sparkHash(id, cycle * 7u + 4u) * 6.2831853;
  let tilt = sqrt(sparkHash(id, cycle * 7u + 5u)) * tuning.x;
  let direction = normalize(axis * cos(tilt) + (side * cos(angle) + up * sin(angle)) * sin(tilt));
  let speed = mix(tuning.y, tuning.z, sparkHash(id, cycle * 7u + 6u));
  let v0 = direction * speed;
  // Linear drag, closed form: x(t) = x0 + (v0 + g/k)(1 − e^{−kt})/k − (g/k) t.
  let g = vec3f(0.0, -ctx.params.gravity, 0.0);
  let decay = exp(-DRAG * t);
  var position = origin + (v0 + g / DRAG) * (1.0 - decay) / DRAG - (g / DRAG) * t;
  var velocity = (v0 + g / DRAG) * decay - g / DRAG;
  // One bounce: fold below the floor, keep a third of the height and slow the skid.
  if (position.y < FLOOR) {
    position = vec3f(origin.x + (position.x - origin.x) * 0.85, FLOOR + (FLOOR - position.y) * 0.3, origin.z + (position.z - origin.z) * 0.85);
    velocity = vec3f(velocity.x * 0.5, -velocity.y * 0.3, velocity.z * 0.5);
  }
  let heat = 1.0 - t / life;
  q.position = position;
  q.endpoint = position - velocity * ctx.params.streak;
  // Cooling is fast: a spark is white-hot on the way up and nearly out by the time it falls.
  q.tint = vec4f(sparkHeat(heat) * ctx.params.brightness * heat * heat * heat, 1.0);
  return q;
}

